def is_power_of_5(x):
    if x <= 0:
        return None # Not a positive power
    k = 0
    while x % 5 == 0:
        x //= 5
        k += 1
    if x == 1:
        return k
    return None

results = {}
for n in range(8, 31):
    X = (2**n) - 3
    k = is_power_of_5(X)
    if k is not None:
        results[n] = k

print("Found pairs (n, k):")
for n, k in results.items():
    print(f"n={n}, k={k}")

def is_power_of_5(x):
    if x <= 0:
        return None
    k = 0
    temp_x = x
    while temp_x % 5 == 0:
        temp_x //= 5
        k += 1
    if temp_x == 1:
        return k
    return None

found_pairs = []
for n in range(8, 31):
    X = (2**n) - 3
    k = is_power_of_5(X)
    if k is not None:
        found_pairs.append((n, k))

print("--- Results ---")
if found_pairs:
    for n, k in found_pairs:
        print(f"n={n}, k={k}")
else:
    print("No solutions found in the range [8, 30].")

def power_mod(base, exponent, modulus):
    return pow(base, exponent, modulus)

n_values = [11, 13, 15]
modulus = 25
results = {}

for n in n_values:
    results[n] = power_mod(2, n, modulus)

print(results)

